13	  // Returns worksheet config from /api/config/workflow, or nulls if not set.
14	  // Throws ApiError/Error if the config endpoint is unreachable.
15	  async function loadWorksheetConfig(): Promise<WorksheetConfig> {
16	    const config = await apiFetch<{
17	      data: { data_panel?: { worksheet_name?: string; available_days_column?: string } } | null;
18	    }>('/api/config/workflow');
19	    return {
20	      worksheetName: config.data?.data_panel?.worksheet_name ?? null,
21	      availableDaysColumn: config.data?.data_panel?.available_days_column ?? null,
22	    };
23	  }
