25	  async function loadWorksheetData(worksheetName: string, availableDaysColumn: string | null): Promise<void> {
26	    dataStore.worksheetState = 'loading';
27	    try {
28	      dataStore.worksheetRows = await getWorksheetData(worksheetName);
29	      dataStore.availableDays = extractAvailableDays(dataStore.worksheetRows, availableDaysColumn);
30	      dataStore.worksheetState = 'done';
31	    } catch {
32	      // Generic message — never expose raw error details to the consultant (AC4)
33	      dataStore.availableDays = null;
34	      dataStore.worksheetError = 'Could not load worksheet data';
35	      dataStore.worksheetState = 'error';
36	    }
37	  }
