39	  async function loadTasks(): Promise<void> {
40	    dataStore.tasksState = 'loading';
41	    try {
42	      const response = await apiFetch<{ data: Array<{ text: string }> }>('/api/data/tasks', {
43	        headers: sessionHeaders(),
44	      });
45	      dataStore.tasks = response.data;
46	      dataStore.tasksState = 'done';
47	    } catch (err) {
48	      const msg =
49	        err instanceof ApiError
50	          ? err.message
51	          : err instanceof Error
52	            ? err.message
53	            : 'Could not load task list';
54	      dataStore.tasksError = msg;
55	      dataStore.tasksState = 'error';
56	    }
57	  }
