59	  onMount(() => {
60	    let active = true; // abort guard — prevents stale promise writes on rapid remount
61	
62	    (async () => {
63	      // Distinguish config fetch failure from worksheet simply not being configured
64	      let worksheetConfig: WorksheetConfig | null = null;
65	      let configFetchError: string | null = null;
66	      try {
67	        worksheetConfig = await loadWorksheetConfig();
68	      } catch (err) {
69	        configFetchError =
70	          err instanceof ApiError ? err.message : 'Could not load configuration';
71	      }
72	
73	      if (!active) return;
74	
75	      const worksheetName = worksheetConfig?.worksheetName ?? null;
76	
77	      // Both fetches run independently — one failure must not block the other (NFR9)
78	      const worksheetPromise = worksheetName
79	        ? loadWorksheetData(worksheetName, worksheetConfig?.availableDaysColumn ?? null)
80	        : (() => {
81	            dataStore.worksheetError = configFetchError ?? 'Worksheet name not configured';
82	            dataStore.worksheetState = 'error';
83	            return Promise.resolve();
84	          })();
85	
86	      await Promise.allSettled([worksheetPromise, loadTasks()]);
87	    })();
88	
89	    return () => {
90	      active = false; // cancel on unmount
91	    };
92	  });
