29	class DataStore {
30	  // Tableau worksheet panel
31	  worksheetRows = $state<WorksheetRow[]>([]);
32	  worksheetState = $state<DataLoadState>('idle');
33	  worksheetError = $state<string | null>(null);
34	
35	  // Consultant's available open days — extracted from worksheetRows on load.
36	  // null when Tableau data is unavailable (triggers graceful capacity check failure).
37	  availableDays = $state<number | null>(null);
38	
39	  // Google Docs task list panel
40	  tasks = $state<TaskItem[]>([]);
41	  tasksState = $state<DataLoadState>('idle');
42	  tasksError = $state<string | null>(null);
43	}
